const saveBatch = `-- name: SaveBatch :one
UPDATE batches SET
    state = $2,
    current_ids = $3,
    pending = $4,
    landed_ids = $5,
    ejected_ids = $6,
    branch_name = $7,
    branch_sha = $8,
    builds = $9,
    ff_retries = $10,
    flaky = $11,
    testing_started_at = $12,
    infra_retries = $13
WHERE id = $1 AND state IN ('forming', 'testing')
RETURNING id, repo_id, target_branch, state, member_ids, current_ids, pending, landed_ids, ejected_ids, branch_name, branch_sha, builds, ff_retries, flaky, created_at, testing_started_at, infra_retries
`

type SaveBatchParams struct {
	ID               int64              `json:"id"`
	State            BatchState         `json:"state"`
	CurrentIds       []int64            `json:"current_ids"`
	Pending          []byte             `json:"pending"`
	LandedIds        []int64            `json:"landed_ids"`
	EjectedIds       []int64            `json:"ejected_ids"`
	BranchName       pgtype.Text        `json:"branch_name"`
	BranchSha        pgtype.Text        `json:"branch_sha"`
	Builds           int32              `json:"builds"`
	FfRetries        int32              `json:"ff_retries"`
	Flaky            bool               `json:"flaky"`
	TestingStartedAt pgtype.Timestamptz `json:"testing_started_at"`
	InfraRetries     int32              `json:"infra_retries"`
}

func (q *Queries) SaveBatch(ctx context.Context, arg SaveBatchParams) (Batch, error) {
	row := q.db.QueryRow(ctx, saveBatch,
		arg.ID,
		arg.State,
		arg.CurrentIds,
		arg.Pending,
		arg.LandedIds,
		arg.EjectedIds,
		arg.BranchName,
		arg.BranchSha,
		arg.Builds,
		arg.FfRetries,
		arg.Flaky,
		arg.TestingStartedAt,
		arg.InfraRetries,
	)
	var i Batch
	err := row.Scan(
		&i.ID,
		&i.RepoID,
		&i.TargetBranch,
		&i.State,
		&i.MemberIds,
		&i.CurrentIds,
		&i.Pending,
		&i.LandedIds,
		&i.EjectedIds,
		&i.BranchName,
		&i.BranchSha,
		&i.Builds,
		&i.FfRetries,
		&i.Flaky,
		&i.CreatedAt,
		&i.TestingStartedAt,
		&i.InfraRetries,
	)
	return i, err
}

const saveCheckStatus = `-- name: SaveCheckStatus :exec
INSERT INTO check_statuses (queue_entry_id, context, state, target_url)
SELECT e.id, $1, $2, $3 FROM queue_entries e WHERE e.id = $4 FOR KEY SHARE
ON CONFLICT (queue_entry_id, context) DO UPDATE
SET state = EXCLUDED.state, target_url = EXCLUDED.target_url, updated_at = NOW()
`

type SaveCheckStatusParams struct {
	Context      string     `json:"context"`
	State        CheckState `json:"state"`
	TargetUrl    string     `json:"target_url"`
	QueueEntryID int64      `json:"queue_entry_id"`
}

// Locks the entry first, like the cascade from entry deletes.
func (q *Queries) SaveCheckStatus(ctx context.Context, arg SaveCheckStatusParams) error {
	_, err := q.db.Exec(ctx, saveCheckStatus,
		arg.Context,
		arg.State,
		arg.TargetUrl,
		arg.QueueEntryID,
	)
	return err
}

