const summarizeEvents = `-- name: SummarizeEvents :many
SELECT r.forge, r.owner, r.name, e.kind, e.reason, COUNT(*)::bigint AS count
FROM queue_events e
JOIN repos r ON r.id = e.repo_id
WHERE e.created_at >= $1
  AND ($2::bigint = 0 OR e.repo_id = $2)
GROUP BY r.forge, r.owner, r.name, e.kind, e.reason
ORDER BY r.forge, r.owner, r.name, e.kind, e.reason
`

type SummarizeEventsParams struct {
	Since  pgtype.Timestamptz `json:"since"`
	RepoID int64              `json:"repo_id"`
}

type SummarizeEventsRow struct {
	Forge  string `json:"forge"`
	Owner  string `json:"owner"`
	Name   string `json:"name"`
	Kind   string `json:"kind"`
	Reason string `json:"reason"`
	Count  int64  `json:"count"`
}

func (q *Queries) SummarizeEvents(ctx context.Context, arg SummarizeEventsParams) ([]SummarizeEventsRow, error) {
	rows, err := q.db.Query(ctx, summarizeEvents, arg.Since, arg.RepoID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SummarizeEventsRow
	for rows.Next() {
		var i SummarizeEventsRow
		if err := rows.Scan(
			&i.Forge,
			&i.Owner,
			&i.Name,
			&i.Kind,
			&i.Reason,
			&i.Count,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const takeQueuedHead = `-- name: TakeQueuedHead :many
SELECT q.id, q.repo_id, q.pr_number, q.pr_head_sha, q.target_branch, q.state, q.enqueued_at, q.testing_started_at, q.completed_at, q.merge_branch_name, q.merge_branch_sha, q.error_message, q.active_batch_id, q.priority, q.infra_retries FROM queue_entries q
WHERE q.repo_id = $1 AND q.target_branch = $2 AND q.state = 'queued'
  -- Priority batches exclude normal PRs so one cannot delay the other via bisection.
  AND (q.priority OR NOT EXISTS (
    SELECT 1 FROM queue_entries p
    WHERE p.repo_id = $1 AND p.target_branch = $2 AND p.state = 'queued' AND p.priority))
ORDER BY q.id
LIMIT $3
FOR NO KEY UPDATE OF q
`

type TakeQueuedHeadParams struct {
	RepoID       int64  `json:"repo_id"`
	TargetBranch string `json:"target_branch"`
	Limit        int32  `json:"limit"`
}

func (q *Queries) TakeQueuedHead(ctx context.Context, arg TakeQueuedHeadParams) ([]QueueEntry, error) {
	rows, err := q.db.Query(ctx, takeQueuedHead, arg.RepoID, arg.TargetBranch, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []QueueEntry
	for rows.Next() {
		var i QueueEntry
		if err := rows.Scan(
			&i.ID,
			&i.RepoID,
			&i.PrNumber,
			&i.PrHeadSha,
			&i.TargetBranch,
			&i.State,
			&i.EnqueuedAt,
			&i.TestingStartedAt,
			&i.CompletedAt,
			&i.MergeBranchName,
			&i.MergeBranchSha,
			&i.ErrorMessage,
			&i.ActiveBatchID,
			&i.Priority,
			&i.InfraRetries,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

